ICON_MAP = {}  # في النسخ المترجمة: «اسم الدور عنوانه» إلى الأيقونة، يملؤها التوليد
ICON_RULES = [("بوصلة", "compass"), ("مدير المكتب", "compass"), ("جودة", "shield"), ("اختبار", "shield"), ("تقني", "code"), ("خلفية", "code"),
              ("مهندس", "code"), ("واجه", "window"), ("إبداع", "star"), ("تصميم", "pen"), ("مصمم", "pen"), ("كاتب", "nib"), ("تحرير", "clipboard"),
              ("منتج", "clipboard"), ("باحث", "search"), ("بحث", "search"), ("نشر", "mega"), ("نمو", "mega"), ("عمليات", "build"), ("تنفيذ", "build"),
              ("حركة", "motion"), ("بصري", "eye"), ("صور", "camera")]
ICON_CYCLE = ["layers", "cube", "scene", "orn", "box", "sparkle", "scissors", "clap"]


def pick_icon(r, i, fallback=True):
    s = "%s %s" % (r["name"], r.get("title", ""))
    if LOCAL is not None:
        return ICON_MAP.get(s) or ICON_CYCLE[i % len(ICON_CYCLE)]
    for kw, ic in ICON_RULES:
        if kw in s:
            return ic
    return ICON_CYCLE[i % len(ICON_CYCLE)] if fallback else None


def parse_stamp(s):
    """«26 أكتوبر 2026، 22:10» إلى ISO بالتوقيت المحلي للمستخدم، أو None."""
    m = re.search(date_rx() + r"[\u060c,\uff0c]?\s*(\d+):(\d+)", s or "")
    if not m:
        return None
    y, mo, d = date_ymd(m)
    return "%04d-%02d-%02dT%02d:%02d:00%s" % (y, mo, d, int(m.group(4)), int(m.group(5)), TZ_ISO)


def clip(s, n):
    s = re.sub(r"\s+", " ", (s or "")).strip()
    return s if len(s) <= n else s[:n].rstrip() + "…"


def dash(s):
    s = (s or "").strip()
    return "" if s in ("—", "-", "") else s


def split_names(cell):
    return [x.strip() for x in re.split(r"[\u060c\u3001\uff0c,+/]| \u0648(?=[^\s])", cell or "") if x.strip() and x.strip() != "—"]


def site_data(root):
    """يبني كائن البيانات بالبنية التي يقرؤها قالب موقع الإدارة."""
    team = load_team(root)
    b = read_board(root)
    owner = team["owner"]
    tasks = b["tasks"]
    status_rows = {role_key(r.get("الدور", "")): r for r in b["team"]}
    by_n = {t["n"]: t for t in tasks}
    names = {role_key(r["name"]): r["name"] for r in team["roster"]}

    def role_of(cell):
        return names.get(role_key(cell), clean_name(cell) if cell else "")

    D_tasks, q_rows, stc = [], [], {}
    for t in tasks:
        st = t["status"].strip() or "محالة"
        if norm(st).startswith("بانتظار اعتماد"):
            st = "بانتظار اعتماد %s" % owner
        stc[st] = stc.get(st, 0) + 1
        deps = [int(x) for x in re.findall(r"\d+", t["after"] or "") if int(x) in by_n]
        open_deps = [d for d in deps if not is_done(by_n[d]["status"])]
        D_tasks.append({"id": t["n"], "frm": role_of(t["from"]) if role_key(t["from"]) in names else t["from"], "to": role_of(t["to"]),
                        "task": clip(t["task"], 600), "due": dash(t["due"]), "st": st, "nxt": clip(dash(t["next"]), 700),
                        "inp": clip(dash(t["inputs"]), 300), "out": clip(dash(t["output"]), 300), "after": dash(t["after"])})
        q_rows.append({"id": t["n"], "to": [role_of(t["to"])], "frm": role_of(t["from"]), "st": st, "task": clip(t["task"], 160),
                       "wait": open_deps, "ready": norm(st) == "محالة" and not open_deps})

    D_team, ei = [], []
    for i, r in enumerate(team["roster"]):
        mine = [t for t in D_tasks if role_key(t["to"]) == role_key(r["name"])]
        sr = status_rows.get(role_key(r["name"]), {})
        doing = [t for t in mine if t["st"] == "قيد التنفيذ"]
        ready = [t for t in mine if t["st"] == "محالة" and next(q for q in q_rows if q["id"] == t["id"])["ready"]]
        waiting = [t for t in D_tasks if t["st"].startswith("بانتظار اعتماد") and role_key(t["to"]) == role_key(r["name"])]
        last = dash(sr.get("آخر نشاط", ""))
        D_team.append({
            "name": r["name"], "title": r["title"], "spec": r["scope"], "plat": norm_platform(r["platform"]), "gpt": norm_platform(r["platform"]) != "Claude",
            "last": last, "at": parse_stamp(last),
            "now": clip("; ".join("الصف %d: %s" % (t["id"], t["task"]) for t in doing[:2]) or dash(sr.get("الحالة", "")) or "", 260),
            "nxt": clip("; ".join("الصف %d" % t["id"] for t in ready[:5]), 260),
            "need": clip("؛ ".join(["اعتماد الصف %d" % t["id"] for t in waiting] + ([dash(sr.get("ملاحظة", ""))] if dash(sr.get("ملاحظة", "")) else [])), 220),
            "cmd": start_cmd(r, team.get("language")), "full": r["chat"]})
        ei.append(pick_icon(r, i))

    circs = []
    for c in b["circulars"]:
        txt = c["text"]
        m = re.match(r"\*\*\((.*?)\)\s*(.*?)\*\*\s*(.*)", txt, re.S)
        if m:
            when, title, body = m.group(1), m.group(2).strip().rstrip(":"), m.group(3).strip()
        else:
            first = re.split(r"(?<=[.:\u061b\u061f!])\s", txt, 1)[0]
            when, title, body = "", clip(first, 90), txt
        circs.append({"n": c["n"], "when": when, "title": title, "text": clip(body or txt, 900)})

    dec = []
    logf = root / "Docs" / "Decision Log.md"
    if logf.exists():
        for d in parse_table(logf.read_text(encoding="utf-8").splitlines()):
            if d.get("#", "").strip().isdigit():
                dec.append({"n": int(d["#"]), "when": d.get("التاريخ", ""), "text": clip(d.get("القرار", ""), 900), "ref": dash(d.get("الوسم", ""))})

    pend = [clip(re.sub(r"\s+", " ", x["text"]), 220) for x in b["decisions"]]

    out = []
    skip_top = {"Office", "Tools", "Archive", ".git"}
    nimg, imgs = 0, {}
    for dp, dn, fn in os.walk(root):
        rel = Path(dp).relative_to(root)
        dn[:] = [d for d in dn if not d.startswith(".") and not (rel == Path(".") and d in skip_top)]
        for f in fn:
            if f.startswith("."):
                continue
            p = Path(dp) / f
            try:
                stt = p.stat()
            except OSError:
                continue
            r = p.relative_to(root).as_posix()
            out.append([r, stt.st_size, int(stt.st_mtime)])
            if f.lower().endswith(IMG_EXT):
                nimg += 1
                g = r.split("/")[0] if "/" in r else "الجذر"
                imgs[g] = imgs.get(g, 0) + 1
    out.sort(key=lambda x: -x[2])
    out = out[:2500]

    gen = now().isoformat(timespec="minutes")
    return {
        "q": {"ts": int(now().timestamp() * 1000), "at": gen, "rows": q_rows},
        "gen": gen, "goal": team["goal"], "goalNow": team["goal"], "feat": "",
        "team": D_team, "tasks": D_tasks, "stc": stc, "nt": len(D_tasks), "nc": len(circs),
        "circs": circs, "dec": dec, "pend": pend,
        "ideas": [], "ch": [], "labels": {}, "dropped": [], "disc": [],
        "imgs": imgs, "nimg": nimg, "th": [], "png": [], "out": out, "links": {}, "att": [{"k": x["kind"], "l": x["label"], "s": x["sev"], "n": x["n"], "who": x["who"], "t": x["text"]} for x in attention(root)],
        "tpl": {"close": CLOSE_T, "resume": RESUME_T}, "ico": ICONS, "ei": ei}


def safe_name(s):
    return re.sub(r"[\\<>\"'`\u2028\u2029]", "", s or "").strip()


def render_site(root):
    team = load_team(root)
    data = site_data(root)
    project = safe_name(team["project"])
    owner = safe_name(team["owner"])
    title = "مكتب إدارة %s" % project
    prefix = "of%s." % hashlib.sha256(project.encode("utf-8")).hexdigest()[:6]
    html = load_template()
    # بدائل نصية داخل شيفرة JS: تُحقن بعد إزالة الرموز المخلة بالنصوص
    for k, v in (("@@TITLE@@", title), ("@@PROJECT@@", project), ("@@OWNER@@", owner), ("@@COMPASSCHAT@@", next((r["chat"] for r in team["roster"] if r["id"] == "compass"), COMPASS)),
                 ("@@COMPASS@@", COMPASS), ("@@PREFIX@@", prefix), ("@@ROOTURI@@", root.resolve().as_uri() + "/")):
        html = html.replace(k, v.replace("&", "&amp;").replace("<", "&lt;") if k in ("@@TITLE@@",) else v)
    if team.get("accent"):
        html = html.replace("#2F5BE0", team["accent"])
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/").replace("<!--", "<\\!--").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    return html.replace("@@DATA@@", payload)


def build_site(root, report=None, open_it=False):
    out = root / "Office" / OFFICE_FILE
    atomic_write(out, render_site(root))
    if report is not None:
        report.append(("بُني", out))
    if open_it:
        import webbrowser
        webbrowser.open(out.as_uri())
    return out


# ---------------------------------------------------------------- الأوامر


def parse_role_spec(spec):
    """«الاسم | المجال | المهام» ← صف دور."""
    parts = [x.strip() for x in str(spec).split("|")]
    name = clean_name(parts[0])
    if not name:
        return None
    title = parts[1] if len(parts) > 1 and parts[1] else name
    scope = parts[2] if len(parts) > 2 and parts[2] else title
    return (name, title, scope, "Claude")


def customize_roles(base, drops, adds):
    roles = list(base)
    for d in drops or []:
        key = role_key(d)
        if key == QA_NAME:
            continue
        roles = [r for r in roles if role_key(r[0]) != key]
    for a in adds or []:
        r = parse_role_spec(a)
        if r and all(role_key(x[0]) != role_key(r[0]) for x in roles):
            roles.append(r)
    if all(role_key(r[0]) != QA_NAME for r in roles):
        roles.append((QA_NAME, "الاختبار المستقل والحكم", "الاختبار المستقل والحكم بيمر أو لا يمر على كل مخرج قبل أن يصل إلى صاحب المشروع", "Claude"))
    return roles


def choose_roles_interactive(base):
    """يعرض الفريق المقترح ويتيح الحذف والإضافة قبل الإنشاء."""
    roles = list(base)
    while True:
        print("\nSuggested team (Compass is added automatically; the QA role cannot be removed):")
        for i, r in enumerate(roles, 1):
            print("  %d) %s: %s" % (i, terminal_label(r[0]), terminal_label(r[1])))
        print("Press Enter to accept, or type:")
        print("  -2        Remove role 2 (or -2,3 for multiple roles)")
        print("  +Role name | Scope     Add a role")
        cmd = input("> ").strip()
        if not cmd:
            return roles
        if cmd[0] in "-−":
            nums = [int(x) for x in re.findall(r"\d+", cmd)]
            drops = [roles[n - 1][0] for n in nums if 1 <= n <= len(roles)]
            roles = customize_roles(roles, drops, [])
        elif cmd[0] == "+":
            roles = customize_roles(roles, [], [cmd[1:]])
        else:
            print("Unknown command. Press Enter to accept the current team.")


def cmd_new(a):
    interactive = sys.stdin.isatty() and not a.yes

    def ask(prompt, default=""):
        if not interactive:
            return default
        v = input("%s%s: " % (prompt, (" [%s]" % default) if default else "")).strip()
        return v or default

    name = a.name or ask("Project name")
    if not name:
        die("Project name is required: new \"Name\" --goal \"One-sentence goal\"")
    goal = a.goal or ask("Project goal in one sentence")
    if not goal:
        die("Project goal is required: --goal \"...\"")
    owner = a.owner or ask("How should the team address you?", "الرئيس")
    preset = a.preset
    if not preset:
        names = list(PRESETS)
        labels = {k: k for k in PRESETS}
        if interactive:
            print("Team type:")
            for g in PRESET_GROUPS:
                items = ["%d) %s" % (i, labels.get(k, k)) for i, k in enumerate(names, 1) if PRESET_META[k][3] == g]
                if items:
                    print("  " + "   ".join(items))
            pick = ask("Choose a number", "1")
            preset = names[int(pick) - 1] if pick.isdigit() and 1 <= int(pick) <= len(names) else (pick if pick in PRESETS else "general")
        else:
            preset = "general"
    if preset not in PRESETS and not a.roles_file:
        die("Unknown team type: %s. Available: %s" % (preset, ", ".join(PRESETS)))
    roles = None
    if a.roles_file:
        data = json.loads(Path(a.roles_file).read_text(encoding="utf-8"))
        roles = [(r["name"], r.get("title", r["name"]), r.get("scope", ""), r.get("platform", "Claude")) for r in data]
    elif a.drop_role or a.add_role:
        roles = customize_roles(PRESETS[preset], a.drop_role, a.add_role)
    elif interactive:
        picked = choose_roles_interactive(PRESETS[preset])
        roles = picked if picked != list(PRESETS[preset]) else None
    parent = a.dest or (str(Path.home() / "Documents" / "Project Forge") if interactive else str(Path.cwd()))
    report = []
    skills = None
    if a.skills == "all":
        skills = list(SKILLS)
    elif a.skills == "none":
        skills = []
    elif a.skills:
        skills = [k.strip() for k in a.skills.split(",")]
    pv = a.platform
    if not pv and interactive:
        pv = {"2": "chatgpt", "3": "grok", "4": "gemini"}.get(ask("Platform: 1) Claude  2) ChatGPT  3) Grok  4) Gemini", "1"), "claude")
    platform = norm_platform(pv) if pv else "Claude"
    if not a.language and interactive:
        a.language = ask("Working language (Arabic, English, Spanish, Macedonian, German, Chinese, Portuguese, Russian)", "العربية")
    if platform != "Claude":
        base = roles if roles else PRESETS[preset]
        roles = [(n, t, sc, platform if norm_platform(pl) == "Claude" else pl) for (n, t, sc, pl) in base]
    root = create_project(parent, name, goal, owner, preset, roles, a.accent, report, skills, platform, a.language or "العربية")
    if a.register:
        try_register(root, a.registry)
    if interactive:
        compass = next(r for r in load_team(root)["roster"] if r["id"] == "compass")
        print("\nProject created successfully (%d files)." % len(report))
        print("Location: %s\n" % root)
        print("Next steps:")
        print("1. The management site will open in your browser (also available at Office/%s)." % OFFICE_FILE)
        print("2. Create a project with the same name in %s and add the project folder from its original location." % platform)
        print("3. Paste this command into the chat to start with Compass:\n")
        print("    " + start_cmd(compass, load_team(root).get("language")))
    else:
        print("Project created: %s\n" % root)
        for k, p in report:
            try:
                rel = p.relative_to(root)
            except ValueError:
                rel = p
            print("  %s  %s" % ({"أُنشئ": "Created", "تُرك": "Kept"}.get(k, k), rel))
        print("\nNext: open Office/%s, then start with Compass." % OFFICE_FILE)
    if interactive:
        try:
            import webbrowser
            webbrowser.open((root / "Office" / OFFICE_FILE).as_uri())
        except Exception:
            pass



def _app_dir():
    h = Path.home()
    if sys.platform == "darwin":
        return h / "Library" / "Application Support" / "Project Forge"
    if os.name == "nt":
        return Path(os.environ.get("LOCALAPPDATA") or (h / "AppData" / "Local")) / "Project Forge"
    return h / ".local" / "share" / "project-forge"


def _desktop_dir():
    d = Path.home() / "Desktop"
    return d if d.is_dir() else Path.home()


def install_shortcut():
    """ينسخ الأداة إلى مكان ثابت وينشئ أيقونة على سطح المكتب تفتح الواجهة بنقرتين.
    الملفات المنشأة محليًا لا يحجبها نظام التشغيل، فلا يظهر تحذير المطوّر غير الموثّق."""
    import base64
    import plistlib
    import stat
    import struct
    home = _app_dir()
    home.mkdir(parents=True, exist_ok=True)
    tool = home / TOOL_NAME
    atomic_write(tool, single_source())
    desk = _desktop_dir()
    png = base64.b64decode("".join(ICON_PNG_B64))
    if sys.platform == "darwin":
        app = desk / "Project Forge.app"
        macos, res = app / "Contents" / "MacOS", app / "Contents" / "Resources"
        macos.mkdir(parents=True, exist_ok=True)
        res.mkdir(parents=True, exist_ok=True)
        run = macos / "ProjectForge"
        py = sys.executable if sys.executable and os.path.isabs(sys.executable) and "/CommandLineTools/" not in sys.executable else ""
        script = (
            '#!/bin/bash\n'
            'export PYTHONUTF8=1\n'
            'T="$HOME/Library/Application Support/Project Forge/%s"\n'
            'LOG="$HOME/Library/Logs/Project Forge.log"\n'
            'mkdir -p "$HOME/Library/Logs"\n'
            'for P in "%s" /opt/homebrew/bin/python3 /usr/local/bin/python3 /Library/Frameworks/Python.framework/Versions/Current/bin/python3 "$HOME/miniconda3/bin/python3" "$HOME/anaconda3/bin/python3" /usr/bin/python3; do\n'
            '  if [ -x "$P" ] && "$P" -c "import sys; sys.exit(0 if sys.version_info >= (3, 9) else 1)" 2>/dev/null; then\n'
            '    exec "$P" -I "$T" gui >>"$LOG" 2>&1\n'
            '  fi\n'
            'done\n'
            '/usr/bin/osascript -e \'display alert "Project Forge" message "Python 3.9 or newer is required. Install it from python.org, then open Project Forge again."\' >/dev/null 2>&1\n'
            'exit 1\n' % (TOOL_NAME, py))
        atomic_write(run, script)
        run.chmod(run.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
        (res / "AppIcon.icns").write_bytes(b"icns" + struct.pack(">I", 16 + len(png)) + b"ic08" + struct.pack(">I", 8 + len(png)) + png)
        (app / "Contents" / "Info.plist").write_bytes(plistlib.dumps({
            "CFBundleName": "Project Forge", "CFBundleDisplayName": "Project Forge", "CFBundleExecutable": "ProjectForge",
            "CFBundleIdentifier": "com.hakamibros.projectforge", "CFBundlePackageType": "APPL", "CFBundleIconFile": "AppIcon",
            "CFBundleVersion": str(VERSION), "CFBundleShortVersionString": "%d.0" % VERSION, "LSMinimumSystemVersion": "10.13"}))
        try:  # توقيع محلي بلا هوية يمنع رفض التشغيل على أجهزة Apple Silicon
            import subprocess
            subprocess.run(["/usr/bin/codesign", "--force", "--deep", "-s", "-", str(app)], capture_output=True, timeout=30)
        except Exception:
            pass
        return app
    if os.name == "nt":
        (home / "icon.png").write_bytes(png)
        bat = desk / "Project Forge.bat"
        atomic_write(bat, "@echo off\r\nchcp 65001 >nul\r\nset PYTHONUTF8=1\r\n"
                          'where pyw >nul 2>nul && (start "" pyw -3 -I "%s" gui & exit /b)\r\n'
                          'where pythonw >nul 2>nul && (start "" pythonw -I "%s" gui & exit /b)\r\n'
                          'python -I "%s" gui\r\n' % (tool, tool, tool))
        return bat
    (home / "icon.png").write_bytes(png)
    entry = desk / "Project Forge.desktop"
    atomic_write(entry, "[Desktop Entry]\nType=Application\nName=Project Forge\nExec=python3 -I \"%s\" gui\nIcon=%s\nTerminal=false\n" % (tool, home / "icon.png"))
    entry.chmod(entry.stat().st_mode | stat.S_IXUSR)
    return entry


def cmd_shortcut(a):
    path = install_shortcut()
    print(gui_msg("Done. Double-click Project Forge on your desktop to open it:\n    %s") % path)


def cmd_gui(a):
    """واجهة رسومية محلية لإنشاء المشروع: خادم على 127.0.0.1 وصفحة في المتصفح."""
    import contextlib
    import http.server
    import io
    import secrets
    import subprocess
    import threading
    import time
    import webbrowser

    token = secrets.token_urlsafe(24)
    state = {"root": None, "ping": None, "start": time.time(), "port": 0}
    default_dest = str(Path.home() / "Documents" / "Project Forge")
    page = load_wizard().replace("@@TOKEN@@", token)

    def presets_payload():
        return {"presets": [{"key": k, "label": PRESET_LABELS.get(k, k), "blurb": PRESET_BLURBS.get(k, ""),
                             "icon": PRESET_META[k][2], "group": PRESET_META[k][3], "tags": preset_tags(k), "syn": PRESET_SYNONYMS.get(k, ""),
                             "roles": [{"name": r[0], "title": r[1], "scope": r[2]} for r in PRESETS[k]]} for k in PRESETS],
                "groups": PRESET_GROUPS, "library": role_library(), "dest": default_dest, "qa": QA_NAME,
                "examples": GOAL_EXAMPLES, "skills": [{"key": k, "name": v[0], "desc": v[1], "group": v[2]} for k, v in SKILLS.items()],
                "skillGroups": SKILL_GROUPS, "recommended": {k: skills_for(k) for k in PRESETS}}

    def create(d):
        name, goal = clean_name(d.get("name", "")), str(d.get("goal", "")).strip()
        if not name or not goal:
            return {"ok": False, "error": "الاسم والهدف مطلوبان."}
        preset = d.get("preset")
        if preset not in PRESETS:
            return {"ok": False, "error": "نوع الفريق غير معروف."}
        owner = str(d.get("owner", "")).strip() or "الرئيس"
        roles = []
        for r in d.get("roles") or []:
            n = clean_name(str(r.get("name", "")))
            if n and all(role_key(n) != role_key(x[0]) for x in roles):
                title = str(r.get("title") or n).strip()
                roles.append((n, title, str(r.get("scope") or title).strip(), norm_platform(r.get("platform") or d.get("platform"))))
        roles = customize_roles(roles, [], [])
        parent = os.path.expanduser(str(d.get("dest", "")).strip() or default_dest)
        skills = [k for k in (d.get("skills") or []) if k in SKILLS] if isinstance(d.get("skills"), list) else None
        err = io.StringIO()
        report = []
        try:
            with contextlib.redirect_stderr(err):
                root = create_project(parent, name, goal, owner, preset, roles, None, report, skills,
                                      platform=d.get("platform"), language=str(d.get("language") or "").strip()[:40])
        except SystemExit:
            return {"ok": False, "error": err.getvalue().strip() or "تعذّر الإنشاء."}
        except OSError as e:
            return {"ok": False, "error": "تعذّر الكتابة في المكان المحدد: %s" % e}
        state["root"] = root
        compass = next(r for r in load_team(root)["roster"] if r["id"] == "compass")
        team = load_team(root)
        code = loc_code(team.get("language"))
        V = loc_variant(code) if code else sys.modules[__name__]
        return {"ok": True, "root": str(root), "cmd": V.start_cmd(compass, team.get("language")), "files": len(report),
                "library": V.commands_library(team), "team": [{"name": r["name"], "title": r["title"], "platform": r["platform"], "cmd": V.start_cmd(r, team.get("language"))} for r in team["roster"]]}

    def open_path(what):
        root = state["root"]
        if not root:
            return
        if what == "office":
            webbrowser.open((root / "Office" / OFFICE_FILE).as_uri())
        elif sys.platform == "darwin":
            subprocess.Popen(["open", str(root)])
        elif os.name == "nt":
            os.startfile(str(root))  # noqa: S606
        else:
            subprocess.Popen(["xdg-open", str(root)])

    class H(http.server.BaseHTTPRequestHandler):
        def log_message(self, *x):
            pass

        def _host_ok(self):
            return self.headers.get("Host", "") in ("127.0.0.1:%d" % state["port"], "localhost:%d" % state["port"])

        def _send(self, code, body, ctype="application/json; charset=utf-8"):
            b = body if isinstance(body, bytes) else body.encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(b)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.end_headers()
            self.wfile.write(b)

        def do_GET(self):
            if not self._host_ok():
                return self._send(403, "{}")
            if self.path.split("?")[0] == "/":
                return self._send(200, page, "text/html; charset=utf-8")
            if self.path == "/api/presets" and self.headers.get("X-Token") == token:
                pl = presets_payload()
                pl["defaults"] = {"platform": norm_platform(os.environ.get("FORGE_PLATFORM")), "language": re.sub(r"[\x00-\x1f<>\"'`]", "", os.environ.get("FORGE_LANGUAGE", "")).strip()[:40]}
                return self._send(200, json.dumps(pl, ensure_ascii=False))
            self._send(404, "{}")

        def do_POST(self):
            if not self._host_ok() or self.headers.get("X-Token") != token:
                return self._send(403, "{}")
            try:
                n = int(self.headers.get("Content-Length") or 0)
                d = json.loads(self.rfile.read(min(n, 1 << 20)).decode("utf-8") or "{}")
            except (ValueError, UnicodeDecodeError):
                return self._send(400, "{}")
            if self.path == "/api/ping":
                state["ping"] = time.time()
                return self._send(200, "{}")
            if self.path == "/api/create":
                return self._send(200, json.dumps(create(d), ensure_ascii=False))
            if self.path == "/api/shortcut":
                try:
                    return self._send(200, json.dumps({"ok": True, "path": str(install_shortcut())}, ensure_ascii=False))
                except OSError as e:
                    return self._send(200, json.dumps({"ok": False, "error": str(e)}, ensure_ascii=False))
            if self.path == "/api/open":
                try:
                    open_path(d.get("what"))
                    return self._send(200, '{"ok": true}')
                except Exception as e:
                    return self._send(200, json.dumps({"ok": False, "error": str(e)}, ensure_ascii=False))
            self._send(404, "{}")

    try:
        srv = http.server.ThreadingHTTPServer(("127.0.0.1", a.port), H)
    except OSError:
        if not a.port:
            die(gui_msg("Could not open a local port. Check your firewall settings and try again."))
        print(gui_msg("Port %d is busy. Choosing another port.") % a.port)
        srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), H)
    state["port"] = srv.server_address[1]
    url = "http://127.0.0.1:%d/" % state["port"]

    def watchdog():
        while True:
            time.sleep(2)
            last = state["ping"]
            grace = 3600 if state["root"] else 120  # المتصفح يبطّئ التبويبات الخلفية، فلا نغلق الخادم بعد الإنشاء
            if (last is None and time.time() - state["start"] > 180) or (last and time.time() - last > grace):
                srv.shutdown()
                return

    threading.Thread(target=watchdog, daemon=True).start()
    print(gui_msg("Project Forge is running. If the page does not open automatically, open this URL:\n\n    %s\n") % url)
    print(gui_msg("The tool stops automatically after the page is closed. To stop immediately, press Ctrl+C."))
    if not a.no_browser:
        opened = False
        if sys.platform == "darwin":
            try:
                opened = subprocess.run(["/usr/bin/open", url], capture_output=True, timeout=15).returncode == 0
            except Exception:
                opened = False
        if not opened:
            try:
                webbrowser.open(url)
            except Exception:
                pass
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    srv.server_close()
    print("Stopped.")


def cmd_build(a):
    root = find_root(a.root)
    out = build_site(root, None, a.open)
    print("Built: %s" % out)


def mtimes(root):
    files = [root / "Agents" / "Board.md", root / "Agents" / "Team.json", root / "Docs" / "Decision Log.md"]
    return tuple(f.stat().st_mtime if f.exists() else 0 for f in files)


def cmd_watch(a):
    root = find_root(a.root)
    last = None
    print("Watching %s (stop: Ctrl+C)" % root)
    try:
        while True:
            m = mtimes(root)
            if m != last:
                last = m
                build_site(root)
                print("%s  Site rebuilt" % now().strftime("%H:%M:%S"))
            time.sleep(a.every)
    except KeyboardInterrupt:
        print("\nStopped watching.")


def cmd_rows(a):
    root = find_root(a.root)
    b = read_board(root)
    mine = [t for t in b["tasks"] if role_key(t["to"]) == role_key(a.role)]
    ready = ready_tasks(b["tasks"], a.role)
    print("Rows for %s: %d ready out of %d" % (a.role, len(ready), len(mine)))
    for t in ready:
        print("\n%d. %s\n   From: %s | Inputs: %s\n   Output: %s" % (t["n"], t["task"], t["from"], t["inputs"], t["output"]))
    cont = [t for t in mine if norm(t["status"]).startswith("قيد التنفيذ") or norm(t["status"]).startswith("اعيدت") or norm(t["status"]).startswith("أعيدت")]
    for t in cont:
        print("\n(%s) %d. %s\n   Next: %s" % (t["status"], t["n"], t["task"], t["next"]))
    if not ready and not cont:
        print("No tasks ready")


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def board_write(root, mutate, by):
    """يقرأ اللوحة، يطبق التعديل، ويتحقق أنها لم تتغير أثناء ذلك؛ وإلا يحفظ مسودة ولا يكتب."""
    p = root / "Agents" / "Board.md"
    before = sha(p)
    text = p.read_text(encoding="utf-8")
    new = mutate(text.splitlines())
    new = touch_updated("\n".join(new) + "\n", by)
    if sha(p) != before:
        draft = root / "Agents" / "Row Drafts" / ("Draft %s.md" % now().strftime("%Y-%m-%d %H%M%S"))
        atomic_write(draft, new)
        die("The board changed during writing. No changes were made. Draft saved to: %s" % draft, 2)
    atomic_write(p, new)


def audit(root, by, action):
    p = root / "Agents" / "Audit Log.md"
    text = p.read_text(encoding="utf-8") if p.exists() else AUDIT_T
    atomic_write(p, text.rstrip("\n") + "\n| %s | %s | %s |\n" % (fmt_dt(now()), esc_cell(by), esc_cell(action)))


def history_add(root, n, status, by):
    p = root / "Data" / "Status History.csv"
    text = p.read_text(encoding="utf-8") if p.exists() else HISTORY_HEAD
    atomic_write(p, text.rstrip("\n") + "\n" + ",".join(csv_cell(x) for x in (n, status, by, now().isoformat(timespec="minutes"))) + "\n")


def csv_cell(v):
    s = str(v)
    return '"%s"' % s.replace('"', '""') if re.search(r'[",\n]', s) else s


def read_history(root):
    p = root / "Data" / "Status History.csv"
    if not p.exists():
        return []
    import csv
    import io
    rows = list(csv.DictReader(io.StringIO(p.read_text(encoding="utf-8-sig"))))
    out = []
    for r in rows:
        try:
            out.append({"n": int(r["n"]), "status": r["status"], "by": r["by"], "at": dt.datetime.fromisoformat(r["at"])})
        except (KeyError, ValueError):
            continue
    return out


def cmd_add_row(a):
    root = find_root(a.root)
    team = load_team(root)
    names = {role_key(r["name"]) for r in team["roster"]} | {role_key(team["owner"])}
    for f in (a.frm, a.to):
        if role_key(f) not in names:
            die("Unknown team member: %s. Available: %s" % (f, "، ".join(sorted(names))))
    b = read_board(root)
    dup = [t for t in b["tasks"] if t["task"].strip() == a.task.strip() and role_key(t["to"]) == role_key(a.to) and not is_done(t["status"])]
    if dup:
        die("An identical row already exists: %d. Nothing was added." % dup[0]["n"])
    opened = [t for t in b["tasks"] if role_key(t["to"]) == role_key(a.to) and not (is_done(t["status"]) or norm(t["status"]).startswith(("ملغ", "مؤجل")))]
    if len(opened) >= a.cap and not a.force:
        die("%s has %d open rows (limit %d). Close some rows or pass --force." % (a.to, len(opened), a.cap))
    n = max([t["n"] for t in b["tasks"]] + [0]) + 1
    row = [n, a.frm, a.to, a.task, a.inputs, a.output, a.after, a.due, "محالة", a.next]
    line = "| " + " | ".join(esc_cell(c) for c in row) + " |"

    def mutate(lines):
        r = section_range(lines, 3)
        if not r:
            die("Board section 3 not found")
        last = None
        for i in range(r[0] + 1, r[1]):
            if lines[i].strip().startswith("|"):
                last = i
        if last is None:
            die("No task table found in section 3")
        return lines[:last + 1] + [line] + lines[last + 1:]

    board_write(root, mutate, a.frm)
    audit(root, a.frm, "أضاف الصف %d إلى %s: %s" % (n, a.to, a.task))
    history_add(root, n, "محالة", a.frm)
    build_site(root)
    print("Added row %d: %s -> %s" % (n, a.frm, a.to))


def cmd_set_status(a):
    root = find_root(a.root)
    team = load_team(root)
    owner = team["owner"]
    st = a.status.strip()
    canon = [s.replace("بانتظار اعتماد", "بانتظار اعتماد %s" % owner) if s == "بانتظار اعتماد" else s for s in STATUSES]
    match = [s for s in canon if norm(s).casefold() == norm(st).casefold()]
    if not match:
        die("Invalid status: %s. Available: %s" % (st, "، ".join(canon)))
    st = match[0]
    if norm(st) in ("معتمدة", "ملغاة") and not a.owner_order:
        die("%s requires an explicit instruction from %s. Add --owner-order only when authorized." % (st, owner), 3)
    def mutate(lines):
        r = section_range(lines, 3)
        hdr = None
        hit = False
        out = list(lines)
        for i in range(r[0] + 1, r[1]):
            ln = lines[i]
            if not ln.strip().startswith("|"):
                continue
            cells = split_row(ln)
            if hdr is None:
                hdr = cells
                continue
            if re.fullmatch(r"\d+", cells[0].strip()) and int(cells[0]) == a.n:
                cells += [""] * (len(hdr) - len(cells))
                cells[hdr.index("الحالة")] = st
                if a.note:
                    cells[hdr.index("للتالي")] = a.note
                out[i] = "| " + " | ".join(esc_cell(c) for c in cells) + " |"
                hit = True
        if not hit:
            die("Row %d not found" % a.n)
        return out

    board_write(root, mutate, a.by or COMPASS)
    audit(root, a.by or COMPASS, "غيّر حالة الصف %d إلى «%s»%s" % (a.n, st, (": " + a.note) if a.note else ""))
    history_add(root, a.n, st, a.by or COMPASS)
    build_site(root)
    print("Row %d -> %s" % (a.n, st))


def regenerate_claude_table(root, team):
    p = root / "CLAUDE.md"
    if not p.exists():
        return
    t = p.read_text(encoding="utf-8")
    new = re.sub(r"<!-- team:start -->.*?<!-- team:end -->", lambda m: "<!-- team:start -->\n%s\n<!-- team:end -->" % team_table(team["roster"]), t, flags=re.S)
    atomic_write(p, new)


def cmd_add_role(a):
    root = find_root(a.root)
    team = load_team(root)
    name = clean_name(a.name)
    if any(role_key(r["name"]) == role_key(name) for r in team["roster"]):
        die("Role already exists: %s" % name)
    n = max(r["n"] for r in team["roster"]) + 1
    r = {"id": "r%d" % n, "n": n, "name": name, "title": a.title or name, "scope": a.scope or "(اكتب الاختصاص)", "platform": a.platform,
         "chat": "%d. %s: %s" % (n, name, a.title or name)}
    team["roster"].append(r)
    save_team(root, team)
    write_new(root / "Agents" / "Roles" / ("%s.md" % name), role_doc(team, r))
    atomic_write(root / "Agents" / "Start Commands.md", start_commands_md(team))
    atomic_write(root / "Agents" / "Commands Library.md", commands_library_md(team))
    regenerate_claude_table(root, team)

    def mutate(lines):
        rg = section_range(lines, 4)
        last = max(i for i in range(rg[0] + 1, rg[1]) if lines[i].strip().startswith("|"))
        row = "| " + " | ".join(esc_cell(c) for c in [name, "فعّال", "—", "0", "—"]) + " |"
        return lines[:last + 1] + [row] + lines[last + 1:]

    board_write(root, mutate, COMPASS)
    build_site(root)
    print("Added role %d. %s; updated rules, commands, board and site." % (n, name))


def cmd_skills(a):
    root = None
    try:
        root = find_root(a.root)
        have = set(load_team(root).get("skills", []))
    except SystemExit:
        have = set()
    for g in SKILL_GROUPS:
        print("\n%s:" % terminal_label(g))
        for k, (n, d, gg, _) in SKILLS.items():
            if gg == g:
                print("  %s %-18s %s: %s" % ("✓" if k in have else " ", k, terminal_label(n), terminal_label(d)))


def cmd_add_skill(a):
    root = find_root(a.root)
    team = load_team(root)
    keys = [k.strip() for k in a.keys.split(",") if k.strip()]
    bad = [k for k in keys if k not in SKILLS]
    if bad:
        die("Unknown skills: %s. Run skills to list available skills." % ", ".join(bad))
    team["skills"] = [k for k in team.get("skills", []) if k in SKILLS]
    for k in keys:
        if k not in team["skills"]:
            team["skills"].append(k)
    save_team(root, team)
    write_skills(root, team["skills"])
    audit(root, team["owner"], "أُضيفت مهارات: %s" % "، ".join(SKILLS[k][0] for k in keys))
    print("Added: %s" % ", ".join(terminal_label(SKILLS[k][0]) for k in keys))


def cmd_decide(a):
    root = find_root(a.root)
    team = load_team(root)
    p = root / "Docs" / "Decision Log.md"
    text = p.read_text(encoding="utf-8") if p.exists() else DECISION_LOG_T
    nums = [int(d["#"]) for d in parse_table(text.splitlines()) if d.get("#", "").strip().isdigit()]
    n = max(nums + [0]) + 1
    tag = a.tag or "قابل للتراجع"
    line = "| %d | %s | %s | %s | %s |" % (n, fmt_date(now()), esc_cell(a.text), esc_cell(tag), esc_cell(a.source or team["owner"]))
    atomic_write(p, text.rstrip("\n") + "\n" + line + "\n")
    audit(root, a.source or team["owner"], "سجّل القرار %d (%s): %s" % (n, tag, a.text))
    build_site(root)
    print("Recorded decision %d (%s)" % (n, tag))


# ---------------------------------------------------------------- التقارير والتصدير

DECISION_SLA_HOURS = 48
OPEN_CAP = 5


def decision_age_hours(text):
    """عمر البند المعلق بالساعات إن ورد فيه تاريخ ووقت، وإلا None."""
    iso = parse_stamp(text)
    if not iso:
        m = re.search(date_rx(), text)
        if not m:
            return None
        iso = "%04d-%02d-%02dT00:00:00%s" % (date_ymd(m) + (TZ_ISO,))
    return (now() - dt.datetime.fromisoformat(iso)).total_seconds() / 3600


def metrics(root):
    team = load_team(root)
    b = read_board(root)
    tasks = b["tasks"]
    hist = read_history(root)
    st = {}
    for t in tasks:
        k = norm(t["status"])
        st[k] = st.get(k, 0) + 1
    done = sum(v for k, v in st.items() if k.startswith(("مسلم", "معتمد")))
    returned = st.get(norm("أعيدت للتعديل"), 0)
    waiting = sum(v for k, v in st.items() if k.startswith("بانتظار"))
    doing = st.get(norm("قيد التنفيذ"), 0)
    assigned = st.get(norm("محالة"), 0)
    closed_by_qa = done + returned
    qa_rate = (done / closed_by_qa * 100) if closed_by_qa else None
    # زمن الدورة: من أول «محالة» إلى أول «مسلّمة/معتمدة» لكل صف
    first_open, first_done = {}, {}
    for h in sorted(hist, key=lambda x: x["at"]):
        s = norm(h["status"])
        if s == "محالة" and h["n"] not in first_open:
            first_open[h["n"]] = h["at"]
        elif s.startswith(("مسلم", "معتمد")) and h["n"] not in first_done:
            first_done[h["n"]] = h["at"]
    cycles = [(first_done[n] - first_open[n]).total_seconds() / 3600 for n in first_done if n in first_open and first_done[n] >= first_open[n]]
    cycle_avg = sum(cycles) / len(cycles) if cycles else None
    week_ago = now() - dt.timedelta(days=7)
    delivered_week = len({h["n"] for h in hist if norm(h["status"]).startswith(("مسلم", "معتمد")) and h["at"] >= week_ago})
    load = []
    for r in team["roster"]:
        mine = [t for t in tasks if role_key(t["to"]) == role_key(r["name"])]
        open_n = sum(1 for t in mine if not (is_done(t["status"]) or norm(t["status"]).startswith(("ملغ", "مؤجل"))))
        load.append({"name": r["name"], "open": open_n, "done": sum(1 for t in mine if is_done(t["status"])), "over": open_n > OPEN_CAP})
    pend = []
    for d in b["decisions"]:
        age = decision_age_hours(d["text"])
        pend.append({"n": d["n"], "text": clip(d["text"], 160), "age": age, "late": age is not None and age > DECISION_SLA_HOURS})
    logf = root / "Docs" / "Decision Log.md"
    ndec = 0
    if logf.exists():
        ndec = sum(1 for d in parse_table(logf.read_text(encoding="utf-8").splitlines()) if d.get("#", "").strip().isdigit())
    nout = sum(1 for p in (root / "Outputs").rglob("*") if p.is_file() and not p.name.startswith(".")) if (root / "Outputs").exists() else 0
    return {"project": team["project"], "owner": team["owner"], "goal": team["goal"], "at": fmt_dt(now()), "total": len(tasks), "done": done,
            "doing": doing, "waiting": waiting, "assigned": assigned, "returned": returned, "qa_rate": qa_rate, "cycle_avg": cycle_avg,
            "cycle_n": len(cycles), "delivered_week": delivered_week, "load": load, "pending": pend, "circulars": len(b["circulars"]),
            "decisions": ndec, "outputs": nout, "team": len(team["roster"]), "attention": attention(root)}


STALL_HOURS = 72
QA_WAIT_HOURS = 24
_AR_DIGITS = str.maketrans("".join(map(chr, [*range(0x660, 0x66A), *range(0x6F0, 0x6FA)])), "01234567890123456789")
ATT_LABELS = {"overdue": "متأخر", "dead": "تبعية معطّلة", "late": "قرار متأخر", "stalled": "راكد", "blocked": "محجوب", "qa": "ينتظر التدقيق", "load": "حمل زائد"}
ATT_SEV = {"overdue": 1, "dead": 1, "late": 1, "stalled": 2, "blocked": 2, "qa": 2, "load": 3}


def parse_due(s):
    """موعد الصف: «2026-10-30» أو «30 أكتوبر 2026». يعيد نهاية ذلك اليوم بالتوقيت المحلي للمستخدم، أو None."""
    s = (s or "").translate(_AR_DIGITS)
    m = re.search(r"(\d{4})[-/](\d{1,2})[-/](\d{1,2})", s)
    try:
        if m:
            y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        else:
            m = re.search(date_rx(), s)
            if not m:
                return None
            y, mo, d = date_ymd(m)
        return dt.datetime(y, mo, d, 23, 59, tzinfo=TZ)
    except ValueError:
        return None


def _count_ar(n, one, two, few, many):
    """عدد مع معدوده بقواعد العربية: يوم، يومان، 3 أيام، 11 يومًا."""
    if n == 1:
        return one
    if n == 2:
        return two
    return "%d %s" % (n, few if 3 <= n <= 10 else many)


def human_span(hours):
    if hours < 1:
        return "أقل من ساعة"
    if hours < 48:
        return _count_ar(round(hours), "ساعة", "ساعتان", "ساعات", "ساعة")
    return _count_ar(round(hours / 24), "يوم", "يومان", "أيام", "يومًا")


def attention(root, at=None):
    """ما يحتاج انتباهًا الآن: صفوف متأخرة أو بتبعية معطّلة أو راكدة أو محجوبة بحاجز راكد، وقرارات تجاوزت مهلتها، وحمل زائد."""
    at = at or now()
    team = load_team(root)
    b = read_board(root)
    by_n = {t["n"]: t for t in b["tasks"]}
    last = {}
    for h in read_history(root):
        if h["n"] not in last or h["at"] > last[h["n"]]:
            last[h["n"]] = h["at"]
    items = []

    def add(kind, n, who, text, hours=None):
        items.append({"kind": kind, "label": ATT_LABELS[kind], "sev": ATT_SEV[kind], "n": n, "who": who, "text": text, "hours": hours})

    def is_open(t):
        s = norm(t["status"])
        return not (is_done(s) or s.startswith(("ملغ", "مؤجل")))

    stalled = {}
    for t in b["tasks"]:
        if not is_open(t):
            continue
        n, st = t["n"], norm(t["status"]) or "محالة"
        who = clean_name(t["to"])
        deps = sorted({int(x) for x in re.findall(r"\d+", t["after"] or "")})
        dead = [d for d in deps if d not in by_n or norm(by_n[d]["status"]).startswith("ملغ")]
        queued = any(d in by_n and is_open(by_n[d]) for d in deps)
        if dead:
            add("dead", n, who, "الصف %d يعتمد على الصف %s الملغى أو غير الموجود؛ أعد تحديد «يبدأ بعد»" % (n, "، ".join(str(d) for d in dead)))
        due = parse_due(t["due"])
        if due and due < at:
            add("overdue", n, who, "الصف %d تجاوز موعده (%s) بمقدار %s عند %s" % (n, due.strftime("%Y-%m-%d"), human_span((at - due).total_seconds() / 3600), who),
                (at - due).total_seconds() / 3600)
        if n in last and not queued and st in ("محالة", "قيد التنفيذ", "أعيدت للتعديل"):
            age = (at - last[n]).total_seconds() / 3600
            if age > STALL_HOURS:
                stalled[n] = age
                add("stalled", n, who, "الصف %d في «%s» منذ %s دون تغيّر عند %s" % (n, st, human_span(age), who), age)
        if n in last and st == "بانتظار التدقيق":
            age = (at - last[n]).total_seconds() / 3600
            if age > QA_WAIT_HOURS:
                add("qa", n, QA_NAME, "الصف %d ينتظر التدقيق منذ %s" % (n, human_span(age)), age)
    overdue_n = {i["n"] for i in items if i["kind"] == "overdue"}
    for t in b["tasks"]:
        if not is_open(t) or norm(t["status"]) not in ("محالة", "قيد التنفيذ"):
            continue
        deps = sorted({int(x) for x in re.findall(r"\d+", t["after"] or "")})
        holders = [d for d in deps if d in stalled or d in overdue_n]
        if holders:
            add("blocked", t["n"], clean_name(t["to"]), "الصف %d محجوب بالصف %s وهو متأخر أو راكد" % (t["n"], "، ".join(str(d) for d in holders)))
    for d in b["decisions"]:
        age = decision_age_hours(d["text"])
        if age is not None and age > DECISION_SLA_HOURS:
            add("late", d["n"], team["owner"], "القرار المعلق %d تجاوز %d ساعة؛ يؤخذ بالتوصية (%s)" % (d["n"], DECISION_SLA_HOURS, clip(d["text"], 70)), age)
    for r in team["roster"]:
        k = sum(1 for t in b["tasks"] if role_key(t["to"]) == role_key(r["name"]) and is_open(t))
        if k > OPEN_CAP:
            add("load", None, r["name"], "%s عنده %d صفوف مفتوحة (السقف %d)" % (r["name"], k, OPEN_CAP))
    items.sort(key=lambda i: (i["sev"], -(i["hours"] or 0), i["n"] or 0))
    return items


def cmd_status(a):
    """إحاطة سريعة من الطرفية: الأرقام وما ينتظرك وما يحتاج انتباهًا."""
    root = find_root(a.root)
    m = metrics(root)
    att = m["attention"]
    if a.json:
        print(json.dumps({"project": m["project"], "at": m["at"], "total": m["total"], "done": m["done"], "doing": m["doing"], "waiting": m["waiting"],
                          "assigned": m["assigned"], "returned": m["returned"], "pending": [{"n": d["n"], "late": d["late"]} for d in m["pending"]],
                          "attention": att}, ensure_ascii=False, indent=2))
        return
    print("%s · %s" % (m["project"], now().isoformat(timespec="seconds")))
    print("Goal: %s" % m["goal"])
    print("")
    print("%d rows: %d delivered · %d in progress · %d waiting · %d assigned · %d returned" % (m["total"], m["done"], m["doing"], m["waiting"], m["assigned"], m["returned"]))
    print("")
    print("Pending your decision (%d):" % len(m["pending"]))
    for d in m["pending"]:
        print("  %d. %s" % (d["n"], d["text"]))
    if not m["pending"]:
        print("  None")
    print("")
    print("Needs attention (%d):" % len(att))
    for i, x in enumerate(att, 1):
        print("  %d. [%s] %s %s | Owner: %s%s" % (i, x["kind"] if LOCAL is None else x["label"], "Decision" if x["kind"] == "late" else "Row", x["n"] if x["n"] is not None else "-", x["who"], " | Age: %.1f hours" % x["hours"] if x["hours"] is not None else ""))
    if not att:
        print("  None: no blockers")
    if a.strict and any(x["sev"] == 1 for x in att):
        sys.exit(2)


def report_md(m):
    pct = lambda v: "—" if v is None else "%d%%" % round(v)
    hrs = lambda v: "—" if v is None else ("%.1f ساعة" % v if v < 48 else "%.1f يوم" % (v / 24))
    out = ["# تقرير أداء %s" % m["project"], "", "**التاريخ:** %s · **الهدف:** %s" % (m["at"], m["goal"]), "", "## 1. الخلاصة", ""]
    out += ["| المؤشر | القيمة |", "| --- | --- |",
            "| المهام الكلية | %d |" % m["total"], "| المسلّمة والمعتمدة | %d (%s) |" % (m["done"], pct(m["done"] / m["total"] * 100 if m["total"] else None)),
            "| قيد التنفيذ | %d |" % m["doing"], "| بانتظار التدقيق أو الاعتماد | %d |" % m["waiting"], "| محالة ولم تبدأ | %d |" % m["assigned"],
            "| أُعيدت للتعديل | %d |" % m["returned"], "| نسبة المرور من ضمان الجودة | %s |" % pct(m["qa_rate"]),
            "| متوسط زمن الدورة (من الإحالة إلى التسليم) | %s |" % ("—" if m["cycle_avg"] is None else "%s، محسوب على %s" % (hrs(m["cycle_avg"]), "صف واحد" if m["cycle_n"] == 1 else "صفين" if m["cycle_n"] == 2 else "%d صفوف" % m["cycle_n"] if m["cycle_n"] <= 10 else "%d صفًا" % m["cycle_n"])),
            "| المسلّم في آخر 7 أيام | %d |" % m["delivered_week"], "| القرارات المسجلة | %d |" % m["decisions"],
            "| القرارات المعلقة | %d (السقف %d) |" % (len(m["pending"]), OPEN_CAP), "| التعميمات | %d |" % m["circulars"],
            "| الفريق | %d دورًا |" % m["team"], "| ملفات المخرجات | %d |" % m["outputs"]]
    out += ["", "## 2. الحمل على الفريق", "", "| الدور | المفتوحة | المسلّمة | ملاحظة |", "| --- | --- | --- | --- |"]
    for r in m["load"]:
        out.append("| %s | %d | %d | %s |" % (r["name"], r["open"], r["done"], "تجاوز السقف" if r["over"] else ""))
    out += ["", "## 3. ما ينتظر قرار %s" % m["owner"], ""]
    if not m["pending"]:
        out.append("(لا شيء)")
    for d in m["pending"]:
        age = "بلا تاريخ" if d["age"] is None else ("متأخر: %s" % hrs(d["age"]) if d["late"] else "منذ %s" % hrs(d["age"]))
        out.append("%d. %s (%s)" % (d["n"], d["text"], age))
    out += ["", "## 4. التنبيهات", ""]
    alerts = [("%s تجاوز سقف الصفوف المفتوحة" % r["name"]) for r in m["load"] if r["over"]]
    alerts += ["القرار المعلق %d تجاوز %d ساعة؛ يؤخذ بالتوصية" % (d["n"], DECISION_SLA_HOURS) for d in m["pending"] if d["late"]]
    alerts += ["%s: %s" % (x["label"], x["text"]) for x in m["attention"] if x["kind"] not in ("load", "late")]
    if len(m["pending"]) > OPEN_CAP:
        alerts.append("القرارات المعلقة تجاوزت السقف")
    if m["returned"] > m["done"] and m["returned"]:
        alerts.append("المعاد للتعديل أكثر من المسلّم: راجع وضوح المهام ومعايير القبول")
    out += ["- " + a for a in alerts] or ["(لا تنبيهات)"]
    return "\n".join(out) + "\n"


def cmd_report(a):
    root = find_root(a.root)
    m = metrics(root)
    text = report_md(m)
    out = root / "Docs" / "Reports" / ("Report %s.md" % now().strftime("%Y-%m-%d"))
    out.parent.mkdir(parents=True, exist_ok=True)
    atomic_write(out, text)
    print("Performance report: %s" % m["project"])
    print("Tasks: %d | Delivered: %d | In progress: %d | Waiting: %d" % (m["total"], m["done"], m["doing"], m["waiting"]))
    print("QA pass rate: %s | Pending decisions: %d" % ("n/a" if m["qa_rate"] is None else "%.1f%%" % m["qa_rate"], len(m["pending"])))
    print("Saved to: %s" % out.relative_to(root))


def cmd_export(a):
    """يصدّر اللوحة والفريق والقرارات والمؤشرات إلى CSV (بترميز UTF-8 مع BOM)."""
    root = find_root(a.root)
    team = load_team(root)
    b = read_board(root)
    d = root / "Data"
    d.mkdir(exist_ok=True)

    def write(name, header, rows):
        lines = [",".join(csv_cell(h) for h in header)] + [",".join(csv_cell(c) for c in r) for r in rows]
        atomic_write(d / name, "﻿" + "\n".join(lines) + "\n")
        return d / name

    hist = read_history(root)
    first = {}
    for h in sorted(hist, key=lambda x: x["at"]):
        s = norm(h["status"])
        if s == "محالة":
            first.setdefault((h["n"], False), h["at"].isoformat(timespec="minutes"))
        elif s.startswith(("مسلم", "معتمد")):
            first.setdefault((h["n"], True), h["at"].isoformat(timespec="minutes"))
    files = [write("Board.csv", ["n", "from", "to", "task", "inputs", "output", "after", "due", "status", "next", "assigned at", "delivered at"],
                   [[t["n"], t["from"], t["to"], t["task"], t["inputs"], t["output"], t["after"], t["due"], t["status"], t["next"],
                     first.get((t["n"], False), ""), first.get((t["n"], True), "")] for t in b["tasks"]])]
    files.append(write("Team.csv", ["n", "name", "title", "scope", "platform", "open", "done"],
                       [[r["n"], r["name"], r["title"], r["scope"], r["platform"],
                         sum(1 for t in b["tasks"] if role_key(t["to"]) == role_key(r["name"]) and not (is_done(t["status"]) or norm(t["status"]).startswith(("ملغ", "مؤجل")))),
                         sum(1 for t in b["tasks"] if role_key(t["to"]) == role_key(r["name"]) and is_done(t["status"]))] for r in team["roster"]]))
    logf = root / "Docs" / "Decision Log.md"
    decs = [d for d in parse_table(logf.read_text(encoding="utf-8").splitlines()) if d.get("#", "").strip().isdigit()] if logf.exists() else []
    files.append(write("Decisions.csv", ["n", "date", "decision", "tag", "source"], [[x["#"], x.get("التاريخ", ""), x.get("القرار", ""), x.get("الوسم", ""), x.get("المصدر", "")] for x in decs]))
    m = metrics(root)
    files.append(write("Metrics.csv", ["metric", "value"], [["total", m["total"]], ["done", m["done"]], ["doing", m["doing"]], ["waiting", m["waiting"]],
                                                            ["assigned", m["assigned"]], ["returned", m["returned"]], ["qa pass rate", "" if m["qa_rate"] is None else round(m["qa_rate"], 1)],
                                                            ["cycle hours avg", "" if m["cycle_avg"] is None else round(m["cycle_avg"], 1)], ["delivered last 7 days", m["delivered_week"]],
                                                            ["pending decisions", len(m["pending"])], ["decisions", m["decisions"]], ["outputs", m["outputs"]], ["generated at", m["at"]]]))
    for f in files:
        print("Exported: %s" % f.relative_to(root))
    print("CSV files are available in Data (UTF-8 with BOM).")


def check_project(root):
    problems = []
    for p in root.rglob("*"):
        if "_" in p.name and ".git" not in p.parts:
            problems.append("اسم فيه شرطة سفلية: %s" % p.relative_to(root))
    team = load_team(root)
    if not any(r["name"] == QA_NAME for r in team["roster"]):
        problems.append("لا يوجد %s في الفريق: لا يمكن ضمان أن مخرجًا يصل إلى %s بحكم مستقل" % (QA_NAME, team["owner"]))
    for r in team["roster"]:
        if not (root / "Agents" / "Roles" / ("%s.md" % r["name"])).exists():
            problems.append("ملف الدور ناقص: %s" % r["name"])
    b = read_board(root)
    nums = [t["n"] for t in b["tasks"]]
    if nums != sorted(set(nums)):
        problems.append("ترقيم اللوحة مكرر أو غير مرتب")
    if nums and min(nums) < 1:
        problems.append("الترقيم يجب أن يبدأ من 1")
    known = {role_key(r["name"]) for r in team["roster"]} | {role_key(team["owner"])}
    canon = {norm(s) for s in STATUSES} | {norm("بانتظار اعتماد %s" % team["owner"])}
    for t in b["tasks"]:
        for f in (t["from"], t["to"]):
            if role_key(f) not in known:
                problems.append("الصف %d: اسم غير معروف «%s»" % (t["n"], f))
        if norm(t["status"]) not in canon:
            problems.append("الصف %d: حالة غير معتمدة «%s»" % (t["n"], t["status"]))
        for d in re.findall(r"\d+", t["after"] or ""):
            if int(d) not in nums:
                problems.append("الصف %d: يبدأ بعد صف غير موجود %s" % (t["n"], d))
    for r in team["roster"]:
        n = sum(1 for t in b["tasks"] if role_key(t["to"]) == role_key(r["name"]) and not (is_done(t["status"]) or norm(t["status"]).startswith(("ملغ", "مؤجل"))))
        if n > 5:
            problems.append("%s: %d صفوف مفتوحة (السقف 5)" % (r["name"], n))
    if len(b["decisions"]) > OPEN_CAP:
        problems.append("القرارات المعلقة %d (السقف %d)" % (len(b["decisions"]), OPEN_CAP))
    for d in b["decisions"]:
        age = decision_age_hours(d["text"])
        if age is not None and age > DECISION_SLA_HOURS:
            problems.append("القرار المعلق %d تجاوز %d ساعة: يؤخذ بالتوصية ويُسجَّل بـ decide" % (d["n"], DECISION_SLA_HOURS))
    return problems


def cmd_check(a):
    root = find_root(a.root)
    pr = check_project(root)
    if not pr:
        print("OK: no issues found.")
        return
    print("%d issues:" % len(pr))
    for i, p in enumerate(pr, 1):
        print("%d. %s" % (i, terminal_diagnostic(p)))
    sys.exit(1)


def try_register(root, registry=None):
    reg = Path(registry) if registry else None
    if reg is None:
        for p in [root.parent] + list(root.parents):
            c = p / "Compass Network" / "Registry.md"
            if c.exists():
                reg = c
                break
    if reg is None or not reg.exists():
        print("Registry.md not found. Pass --registry or run register later.")
        return False
    team = load_team(root)
    text = reg.read_text(encoding="utf-8")
    rel = "%s/%s" % (reg.parent.parent.name, os.path.relpath(root, reg.parent.parent))
    if "`%s`" % rel in text:
        print("Project already registered in %s" % reg)
        return True
    nums = [int(m.group(1)) for m in re.finditer(r"^\|\s*(\d+)\s*\|", text, re.M)]
    n = max(nums + [0]) + 1
    row = "| %d | %s | `%s` | %s | فعّال | %s | %s |" % (n, team["project"], rel, esc_cell(team["goal"]), fmt_date(now()), fmt_dt(now()))
    atomic_write(reg, text.rstrip("\n") + "\n" + row + "\n")
    print("Registered in %s (number %d)" % (reg, n))
    return True


def cmd_register(a):
    try_register(find_root(a.root), a.registry)


def cmd_selftest(a):
    tmp = Path(tempfile.mkdtemp(prefix="forge selftest "))
    ok = True

    def step(name, cond):
        nonlocal ok
        print("%s  %s" % ("PASS" if cond else "FAIL", name))
        ok = ok and bool(cond)

    try:
        rep = []
        root = create_project(tmp, "مشروع تجريبي", "اختبار الأداة", "الرئيس", "general", None, None, rep)
        step("Create project and files", (root / "CLAUDE.md").exists() and (root / "Agents" / "Board.md").exists() and (root / "Office" / OFFICE_FILE).exists())
        step("Bundled project tool", (root / "Tools" / TOOL_NAME).exists())
        step("No underscores in names", not [p for p in root.rglob("*") if "_" in p.name])
        step("Initial project checks", check_project(root) == [])
        ns = argparse.Namespace(root=str(root), frm="البوصلة", to="رئيس المنتج", task="كتابة المرجع", inputs="—", output="`Outputs/x.md`", after="1", due="—", next="—", cap=5, force=False)
        cmd_add_row(ns)
        b = read_board(root)
        step("Sequential row numbering", [t["n"] for t in b["tasks"]] == [1, 2])
        step("Dependency blocks task before delivery", ready_tasks(b["tasks"], "رئيس المنتج") == [])
        cmd_set_status(argparse.Namespace(root=str(root), n=1, status="مسلّمة", note="تم", by=None, owner_order=False))
        step("Task becomes ready after delivery", len(ready_tasks(read_board(root)["tasks"], "رئيس المنتج")) == 1)
        try:
            cmd_set_status(argparse.Namespace(root=str(root), n=1, status="معتمدة", note=None, by=None, owner_order=False))
            blocked = False
        except SystemExit as e:
            blocked = e.code == 3
        step("Approval requires owner authorization", blocked)
        cmd_add_role(argparse.Namespace(root=str(root), name="المحلل", title="محلل البيانات", scope="التحليل", platform="Claude"))
        step("Adding a role updates rules and site", "المحلل" in (root / "CLAUDE.md").read_text(encoding="utf-8") and (root / "Agents" / "Roles" / "المحلل.md").exists())
        cmd_decide(argparse.Namespace(root=str(root), text="اختبار قرار", tag=None, source=None))
        html = (root / "Office" / OFFICE_FILE).read_text(encoding="utf-8")
        step("Site contains project data", "اختبار قرار" in html and "كتابة المرجع" in html and "المحلل" in html)
        step("Project checks after edits", check_project(root) == [])
        step("No unresolved site placeholders", "@@" not in html)
        m = re.search(r"var D=(\{.*?\});\nvar \$=", html, re.S)
        try:
            d = json.loads(m.group(1)) if m else None
        except ValueError:
            d = None
        step("Valid site JSON with team and tasks", bool(d) and len(d["team"]) >= 7 and d["nt"] == 2 and d["dec"][0]["text"] == "اختبار قرار")
        tool_copy = (root / "Tools" / TOOL_NAME).read_text(encoding="utf-8")
        step("Project tool is standalone", '_TEMPLATE_Z = """' in tool_copy and len(tool_copy) > 100000)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    print("\n" + ("All tests passed" if ok else "Some tests failed"))
    sys.exit(0 if ok else 1)


ARGPARSE_TEXTS = {
    "argparse:usage: ": "usage: ",
    "argparse:positional arguments": "positional arguments",
    "argparse:options": "options",
    "argparse:optional arguments": "optional arguments",
    "argparse:show this help message and exit": "show this help message and exit",
    "argparse:%(prog)s: error: %(message)s\n": "%(prog)s: error: %(message)s\n",
    "argparse:the following arguments are required: %s": "the following arguments are required: %s",
    "argparse:unrecognized arguments: %s": "unrecognized arguments: %s",
    "argparse:invalid choice: %(value)r (choose from %(choices)s)": "invalid choice: %(value)r (choose from %(choices)s)",
    "argparse:argument %(argument_name)s: %(message)s": "argument %(argument_name)s: %(message)s",
    "argparse:expected one argument": "expected one argument",
    "argparse:expected at most one argument": "expected at most one argument",
    "argparse:expected at least one argument": "expected at least one argument",
    "argparse:invalid %(type)s value: %(value)r": "invalid %(type)s value: %(value)r",
    "argparse:ambiguous option: %(option)s could match %(matches)s": "ambiguous option: %(option)s could match %(matches)s",
    "argparse:not allowed with argument %s": "not allowed with argument %s",
    "argparse:ignored explicit argument %r": "ignored explicit argument %r",
    "argparse:one of the arguments %s is required": "one of the arguments %s is required",
    "argparse:expected %s argument": "expected %s argument",
    "argparse:expected %s arguments": "expected %s arguments",
    "argparse:subcommand": "subcommand",
    "argparse:unknown parser %(parser_name)r (choices: %(choices)s)": "unknown parser %(parser_name)r (choices: %(choices)s)",
}


def argparse_i18n():
    """يترجم عناوين argparse ورسائله (usage وoptions...) بلغة الأداة؛ النسخة الأم تتبع FORGE_LANGUAGE، والعربية والإنجليزية تبقيان بالإنجليزية."""
    def f(s):
        return ARGPARSE_TEXTS.get("argparse:" + s, s)
    if LOCAL is None:
        def f(s):
            return gui_msg(ARGPARSE_TEXTS.get("argparse:" + s, s))
    argparse._ = f
    argparse.ngettext = lambda one, many, n: f(one) if n == 1 else f(many)

    def err_str(self):  # هذه الصيغة ثابتة في argparse ولا تمر على المترجم
        fmt = "%(message)s" if self.argument_name is None else f("argument %(argument_name)s: %(message)s")
        return fmt % dict(message=self.message, argument_name=self.argument_name)
    argparse.ArgumentError.__str__ = err_str


def main(argv=None):
    argparse_i18n()
    ap = argparse.ArgumentParser(prog=TOOL_NAME, description="Project Forge: create an AI team project and its management site")
    ap.add_argument("--root", help="Project root (detected automatically)")
    sp = ap.add_subparsers(dest="cmd")

    p = sp.add_parser("new", help="Create a complete project")
    p.add_argument("name", nargs="?")
    p.add_argument("--goal")
    p.add_argument("--owner")
    p.add_argument("--preset", choices=list(PRESETS))
    p.add_argument("--platform", choices=["claude", "chatgpt", "grok", "gemini"], help="Chat platform: claude (default), chatgpt, grok or gemini")
    p.add_argument("--language", help="Working language: Arabic (default), English, Spanish, Macedonian, German, Chinese, Portuguese or Russian")
    p.add_argument("--roles-file", help="JSON role list: [{name,title,scope,platform}]")
    p.add_argument("--drop-role", action="append", help="Remove a preset role (repeatable)")
    p.add_argument("--add-role", action="append", help="Add a role as \"name | title | scope\" (repeatable)")
    p.add_argument("--skills", help="Skills: all, none, or comma-separated keys (default: preset recommendations)")
    p.add_argument("--dest", help="Parent directory for the new project")
    p.add_argument("--accent", help="Accent color as #RRGGBB for light mode")
    p.add_argument("--register", action="store_true", help="Register the project in the Compass hub")
    p.add_argument("--registry", help="Path to Registry.md")
    p.add_argument("--yes", action="store_true", help="Skip interactive prompts")
    p.set_defaults(fn=cmd_new)

    if LOCAL is None:
        p = sp.add_parser("gui", help="Open the creation wizard (default when no command is given)")
        p.add_argument("--no-browser", action="store_true")
        p.add_argument("--port", type=int, default=0)
        p.set_defaults(fn=cmd_gui)
        sp.add_parser("shortcut", help="Create a desktop shortcut for the wizard").set_defaults(fn=cmd_shortcut)

    p = sp.add_parser("build", help="Build the management site")
    p.add_argument("--open", action="store_true")
    p.set_defaults(fn=cmd_build)
    p = sp.add_parser("watch", help="Rebuild automatically")
    p.add_argument("--every", type=float, default=2.0)
    p.set_defaults(fn=cmd_watch)
    p = sp.add_parser("rows", help="List ready rows for a role")
    p.add_argument("role")
    p.set_defaults(fn=cmd_rows)

    p = sp.add_parser("add-row", help="Add a board row")
    p.add_argument("--from", dest="frm", required=True)
    p.add_argument("--to", required=True)
    p.add_argument("--task", required=True)
    p.add_argument("--inputs", default="—")
    p.add_argument("--output", default="—")
    p.add_argument("--after", default="—")
    p.add_argument("--due", default="—")
    p.add_argument("--next", default="—")
    p.add_argument("--cap", type=int, default=5)
    p.add_argument("--force", action="store_true")
    p.set_defaults(fn=cmd_add_row)

    p = sp.add_parser("set-status", help="Change a row status")
    p.add_argument("n", type=int)
    p.add_argument("status")
    p.add_argument("--note")
    p.add_argument("--by")
    p.add_argument("--owner-order", action="store_true")
    p.set_defaults(fn=cmd_set_status)

    p = sp.add_parser("add-role", help="Add a role")
    p.add_argument("name")
    p.add_argument("--title")
    p.add_argument("--scope")
    p.add_argument("--platform", default="Claude")
    p.set_defaults(fn=cmd_add_role)

    p = sp.add_parser("decide", help="Record a decision")
    p.add_argument("text")
    p.add_argument("--tag")
    p.add_argument("--source")
    p.set_defaults(fn=cmd_decide)

    sp.add_parser("skills", help="List available skills").set_defaults(fn=cmd_skills)
    p = sp.add_parser("add-skill", help="Add skills to the project: add-skill measure,deck")
    p.add_argument("keys")
    p.set_defaults(fn=cmd_add_skill)
    sp.add_parser("report", help="Performance report: metrics, workload and overdue decisions").set_defaults(fn=cmd_report)
    p = sp.add_parser("status", help="Status: metrics, pending decisions and items needing attention")
    p.add_argument("--json", action="store_true", help="Machine-readable JSON output")
    p.add_argument("--strict", action="store_true", help="Exit with code 2 when urgent items exist")
    p.set_defaults(fn=cmd_status)
    sp.add_parser("export", help="Export board, team, decisions and metrics as CSV").set_defaults(fn=cmd_export)
    sp.add_parser("check", help="Check the project").set_defaults(fn=cmd_check)
    p = sp.add_parser("register", help="Register in the Compass hub")
    p.add_argument("--registry")
    p.set_defaults(fn=cmd_register)
    sp.add_parser("selftest", help="Run a self-test").set_defaults(fn=cmd_selftest)

    a = ap.parse_args(argv)
    if not getattr(a, "cmd", None):
        if LOCAL is not None:
            ap.print_help()
            return
        a.fn, a.no_browser, a.port = cmd_gui, False, 0
    a.fn(a)


if __name__ == "__main__":
    main()
